pub fn fold_call_lowering(fold_call: Rc<Node>) -> Rc<FoldCallLowering> {
    fold_call_lowering_from(fold_call, Rc::new(FoldCollectionSource::CollectionInCall))
}

pub fn fold_call_lowering_piped(fold_call: Rc<Node>, receiver: Rc<Node>) -> Rc<FoldCallLowering> {
    fold_call_lowering_from(fold_call, Rc::new(FoldCollectionSource::CollectionPiped {
    receiver: receiver.clone(),
}))
}

pub fn fold_call_lowering_from(fold_call: Rc<Node>, source: Rc<FoldCollectionSource>) -> Rc<FoldCallLowering> {
    match fold_call_head_symbol(fold_call.clone()) {
    std::option::Option::None => Rc::new(FoldCallLowering::FoldCallNotAFold {
    diagnostic: fold_lowering_not_a_fold_call_diagnostic(fold_call.clone()),
}),
    Some(head) => match fold_family_realization(head.clone()) {
    std::option::Option::None => Rc::new(FoldCallLowering::FoldCallNotAFold {
    diagnostic: fold_lowering_not_a_fold_call_diagnostic(fold_call.clone()),
}),
    Some(realization) => {
        let slots = fold_slots_for_source(fold_realization_slots(realization.clone()), source.clone());
match (*fold_realization_form(realization.clone())).clone() {
    CollectionRosterForm::RosterAuthoredStep => fold_call_lowering_of(fold_call.clone(), slots.clone(), source.clone()),
    CollectionRosterForm::RosterCallbackStep { realization: callback, .. } => fold_call_callback_lowering_of(fold_call.clone(), slots.clone(), source.clone(), callback.clone()),
    CollectionRosterForm::RosterFreeMonoidPrimitiveCall => Rc::new(FoldCallLowering::FoldCallNotAFold {
    diagnostic: fold_lowering_not_a_fold_call_diagnostic(fold_call.clone()),
}),
}
},
},
}
}

pub fn fold_call_lowering_of(fold_call: Rc<Node>, slots: Rc<FoldSlots>, source: Rc<FoldCollectionSource>) -> Rc<FoldCallLowering> {
    match (*fold_call_step_form(fold_call.clone(), slots.clone())).clone() {
    FoldStepForm::StepByName => Rc::new(FoldCallLowering::FoldCallStepFormUnresolved {
    diagnostic: fold_lowering_step_form_unresolved_diagnostic(fold_call.clone()),
}),
    FoldStepForm::StepFnLiteral { literal: fn_literal, .. } => fold_call_operands_from_step(fold_call.clone(), slots.clone(), source.clone(), step_fn_iteration_body(fn_literal.clone()), step_fn_carrier_binder_symbol(fn_literal.clone())),
    FoldStepForm::StepArrowLambda { lambda: lambda, .. } => fold_call_operands_from_step(fold_call.clone(), slots.clone(), source.clone(), arrow_lambda_iteration_body(lambda.clone()), arrow_lambda_carrier_binder_symbol(lambda.clone())),
}
}

pub fn fold_callback_has_one_binder(parts: Option<Rc<FunctionValueParts>>) -> bool {
    match parts.clone() {
    Some(p) => { let __fm = p.binders.clone(); if __fm.len() == 1 { true } else { false } },
    std::option::Option::None => false,
}
}

pub fn fold_call_callback_lowering_of(fold_call: Rc<Node>, slots: Rc<FoldSlots>, source: Rc<FoldCollectionSource>, realization: CallbackRealization) -> Rc<FoldCallLowering> {
    {
        let one_binder = match (*fold_call_step_form(fold_call.clone(), slots.clone())).clone() {
    FoldStepForm::StepByName => crate::std_optional::optional_absent(),
    FoldStepForm::StepFnLiteral { literal: fn_literal, .. } => crate::std_optional::optional_present(fold_callback_has_one_binder(fn_literal_parts_optional(fn_literal.clone()))),
    FoldStepForm::StepArrowLambda { lambda: lambda, .. } => crate::std_optional::optional_present(fold_callback_has_one_binder(arrow_lambda_parts_optional(lambda.clone()))),
};
match one_binder.clone() {
    std::option::Option::None => Rc::new(FoldCallLowering::FoldCallStepFormUnresolved {
    diagnostic: fold_lowering_step_form_unresolved_diagnostic(fold_call.clone()),
}),
    Some(has_one) => if !has_one.clone() {
            Rc::new(FoldCallLowering::FoldCallStepShapeInvalid {
    diagnostic: fold_lowering_shape_invalid_diagnostic(fold_call.clone()),
})
        } else {
            match fold_call_head_node(fold_call.clone()) {
    std::option::Option::None => Rc::new(FoldCallLowering::FoldCallNotAFold {
    diagnostic: fold_lowering_not_a_fold_call_diagnostic(fold_call.clone()),
}),
    Some(head_node) => match fold_call_slot_value(fold_call.clone(), slots.step.clone()) {
    std::option::Option::None => Rc::new(FoldCallLowering::FoldCallStepShapeInvalid {
    diagnostic: fold_lowering_shape_invalid_diagnostic(fold_call.clone()),
}),
    Some(callback) => match fold_call_collection(fold_call.clone(), slots.clone(), source) {
    std::option::Option::None => Rc::new(FoldCallLowering::FoldCallOperandAbsent {
    diagnostic: fold_lowering_operand_absent_diagnostic(fold_call.clone()),
}),
    Some(collection) => Rc::new(FoldCallLowering::FoldCallCallbackLowered {
    operands: Rc::new(CallbackCallOperands {
    head: head_node.clone(),
    collection: collection.clone(),
    callback: callback.clone(),
    realization: realization.clone(),
}),
}),
},
},
}
        },
}
}
}

pub fn fold_call_step_carrier(fold_call: Rc<Node>) -> Option<std::string::String> {
    match fold_call_head_symbol(fold_call.clone()) {
    std::option::Option::None => crate::std_optional::optional_absent(),
    Some(head) => match fold_family_authored_step_realization(head.clone()) {
    std::option::Option::None => crate::std_optional::optional_absent(),
    Some(realization) => match (*fold_call_step_form(fold_call.clone(), fold_realization_slots(realization.clone()))).clone() {
    FoldStepForm::StepByName => crate::std_optional::optional_absent(),
    FoldStepForm::StepFnLiteral { literal: fn_literal, .. } => match step_fn_iteration_body(fn_literal.clone()) {
    std::option::Option::None => crate::std_optional::optional_absent(),
    Some(_) => step_fn_carrier_binder_symbol(fn_literal.clone()),
},
    FoldStepForm::StepArrowLambda { lambda: lambda, .. } => match arrow_lambda_iteration_body(lambda.clone()) {
    std::option::Option::None => crate::std_optional::optional_absent(),
    Some(_) => arrow_lambda_carrier_binder_symbol(lambda.clone()),
},
},
},
}
}

pub fn fold_call_to_encoding(fold_call: Rc<Node>) -> Rc<Outcome<Rc<Node>>> {
    match (*fold_call_lowering(fold_call)).clone() {
    FoldCallLowering::FoldCallLowered { operands: operands, .. } => crate::v2_std_diagnostic::outcome_accepted(fold_recurrence_encoding(operands.clone())),
    FoldCallLowering::FoldCallCallbackLowered { operands: operands, .. } => crate::v2_std_diagnostic::outcome_rejected(fold_lowering_callback_step_unbuilt_diagnostic(operands.head.clone())),
    FoldCallLowering::FoldCallNotAFold { diagnostic: d, .. } => crate::v2_std_diagnostic::outcome_rejected(d.clone()),
    FoldCallLowering::FoldCallStepFormUnresolved { diagnostic: d, .. } => crate::v2_std_diagnostic::outcome_rejected(d.clone()),
    FoldCallLowering::FoldCallStepShapeInvalid { diagnostic: d, .. } => crate::v2_std_diagnostic::outcome_rejected(d.clone()),
    FoldCallLowering::FoldCallOperandAbsent { diagnostic: d, .. } => crate::v2_std_diagnostic::outcome_rejected(d.clone()),
}
}

